<?php function db_connect() { $conn = pg_connect("host=db port=5432 dbname=example user=localuser password=cs4640LocalUser!"); if (!$conn) { throw new Exception("Failed to connect: " . pg_last_error()); } return $conn; } function db_query($conn, $query, $params = array()) { $result = pg_query_params($conn, $query, $params); if (!$result) { throw new Exception("Query failed: " . pg_last_error($conn)); } return $result; } function db_fetch_assoc($result) { return pg_fetch_assoc($result); } function db_fetch_all($result) { $rows = array(); while ($row = pg_fetch_assoc($result)) { $rows[] = $row; } return $rows; } function db_num_rows($result) { return pg_num_rows($result); } function db_last_insert_id($conn) { $result = pg_query($conn, "SELECT lastval()"); if ($result) { $row = pg_fetch_row($result); return $row[0]; } return null; } function db_close($conn) { return pg_close($conn); } ?>
